#include "q2k.cuh"
#include "vecdotq.cuh"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <algorithm>
#include <functional>
using namespace halo6000;
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}
static std::vector<uint8_t>read(const char*p){FILE*f=fopen(p,"rb");if(!f){perror(p);exit(3);}fseek(f,0,SEEK_END);size_t n=ftell(f);rewind(f);std::vector<uint8_t>v(n);if(fread(v.data(),1,n,f)!=n)exit(3);fclose(f);return v;}
template<int LG,bool Native>__global__ void project(MatrixView w,ActivationView a,const block_q8_1*q,float*out,int B,int E){int row=blockIdx.x*(blockDim.x/LG)+threadIdx.x/LG,vec=blockIdx.y,lane=threadIdx.x%LG;if(row>=w.n)return;int e=vec%E;float v=0;if constexpr(Native){const Q2KBlock*p=q2k_weights(w,row,e);for(int i=lane;i<w.k/16;i+=LG)v+=vec_dot_q2_K_q8_1(p,q+vec*(w.k/32)+(i/16)*8,i/16,i%16);for(int s=LG/2;s;s/=2)v+=__shfl_down_sync(~0u,v,s,LG);}else v=q2k_row<LG>(w,a,row,e,vec);if(!lane)out[(size_t)vec*w.n+row]=v;}
__global__ void flush(const int4*a,int4*b,size_t n){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x;if(i<n)b[i]=a[i];}
template<int LG>void measure(MatrixView w,ActivationView a,block_q8_1*q,float*out,float*reference,int B,int E,bool timing,cudaStream_t st){int blocks=(w.n+256/LG-1)/(256/LG);auto run=[=](){project<LG,false><<<dim3(blocks,B*E),256,0,st>>>(w,a,q,out,B,E);};project<LG,true><<<dim3(blocks,B*E),256,0,st>>>(w,a,q,reference,B,E);run();ck(cudaStreamSynchronize(st));std::vector<float>got(size_t(B)*E*w.n),native(got.size());ck(cudaMemcpy(got.data(),out,got.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(native.data(),reference,native.size()*4,cudaMemcpyDeviceToHost));size_t bad=0;double maxdiff=0;for(size_t i=0;i<got.size();i++){bad+=memcmp(&got[i],&native[i],4)!=0;maxdiff=std::max(maxdiff,double(fabsf(got[i]-native[i])));}if(bad){fprintf(stderr,"Q2K native mismatch LG%d B%d bad%zu err%g\n",LG,B,bad,maxdiff);exit(4);}float us=0;
if(timing){int4*fa,*fb;size_t fn=16*1024*1024;ck(cudaMalloc(&fa,fn*16));ck(cudaMalloc(&fb,fn*16));ck(cudaMemset(fa,1,fn*16));cudaGraph_t g;cudaGraphExec_t ex;ck(cudaStreamBeginCapture(st,cudaStreamCaptureModeGlobal));run();ck(cudaStreamEndCapture(st,&g));ck(cudaGraphInstantiate(&ex,g));cudaEvent_t s,z;ck(cudaEventCreate(&s));ck(cudaEventCreate(&z));std::vector<float>samples;for(int r=0;r<24;r++){flush<<<(fn+255)/256,256,0,st>>>(fa,fb,fn);ck(cudaEventRecord(s,st));ck(cudaGraphLaunch(ex,st));ck(cudaEventRecord(z,st));ck(cudaEventSynchronize(z));float ms;ck(cudaEventElapsedTime(&ms,s,z));if(r>=4)samples.push_back(ms*1000);}std::sort(samples.begin(),samples.end());us=samples[samples.size()/2];ck(cudaGraphExecDestroy(ex));ck(cudaGraphDestroy(g));ck(cudaEventDestroy(s));ck(cudaEventDestroy(z));ck(cudaFree(fa));ck(cudaFree(fb));}
printf("{\"rows\":%d,\"experts\":%d,\"N\":%d,\"K\":%d,\"lanes\":%d,\"native_guard_values\":%zu,\"different_bits\":%zu,\"max_abs_vs_native\":%.9g,\"cold_us\":%.3f,\"original_activation_sum_is_nan\":true}\n",B,E,w.n,w.k,LG,got.size(),bad,maxdiff,us);fflush(stdout);}
int main(int argc,char**argv){if(argc<2)return 1;bool timing=argc>2&&!strcmp(argv[2],"timing");auto host=read(argv[1]);int N=2048,K=512,E=8;if(host.size()!=size_t(N)*K/256*84*E)return 3;MatrixView w;w.n=N;w.k=K;w.experts=E;w.row_stride=K/256*84;w.expert_stride=w.row_stride*N;w.bytes=host.size();void*weights;ck(cudaMalloc(&weights,host.size()));ck(cudaMemcpy(weights,host.data(),host.size(),cudaMemcpyHostToDevice));w.data=weights;cudaStream_t st;ck(cudaStreamCreate(&st));
for(int B:{1,8,32,128,512}){std::vector<int8_t>qs(size_t(B)*E*K);std::vector<float>ds(qs.size()/32);std::vector<block_q8_1>raw(ds.size());for(size_t i=0;i<ds.size();i++){ds[i]=__half2float(__float2half(.007f+.001f*(i%5)));raw[i].ds=__halves2half2(__float2half(ds[i]),__float2half(NAN));for(int k=0;k<32;k++)raw[i].qs[k]=qs[i*32+k]=(i*97+k*31)%255-127;}ActivationView a;a.k=K;a.rows=B*E;a.group=32;a.q_stride=K;a.scale_stride=K/32;int8_t*ad;float*sd;block_q8_1*qd;float*out,*ref;ck(cudaMalloc(&ad,qs.size()));ck(cudaMemcpy(ad,qs.data(),qs.size(),cudaMemcpyHostToDevice));ck(cudaMalloc(&sd,ds.size()*4));ck(cudaMemcpy(sd,ds.data(),ds.size()*4,cudaMemcpyHostToDevice));ck(cudaMalloc(&qd,raw.size()*sizeof(block_q8_1)));ck(cudaMemcpy(qd,raw.data(),raw.size()*sizeof(block_q8_1),cudaMemcpyHostToDevice));a.qs=ad;a.scale=sd;ck(cudaMalloc(&out,size_t(B)*E*N*4));ck(cudaMalloc(&ref,size_t(B)*E*N*4));measure<4>(w,a,qd,out,ref,B,E,timing,st);measure<8>(w,a,qd,out,ref,B,E,timing,st);measure<16>(w,a,qd,out,ref,B,E,timing,st);measure<32>(w,a,qd,out,ref,B,E,timing,st);
// Independent original-weight dequantization; q2 byte order follows CPU GGML,
// rather than the helper's four-component slice decomposition.
double maxerr=0;for(int token:{0,B-1})for(int expert:{0,E-1})for(int row:{0,1,N/2,N-1}){double expect=0;const auto*p=(const Q2KBlock*)host.data()+(expert*N+row)*(K/256);for(int k=0;k<K;k++){auto&b=p[k/256];int j=k%256,scale=j/16,shift=(j%128)/32*2,offset=(j/128)*32+j%32;float d=__half2float(*reinterpret_cast<const half*>(&b.d)),m=__half2float(*reinterpret_cast<const half*>(&b.dmin));float weight=d*(b.scales[scale]&15)*((b.qs[offset]>>shift)&3)-m*(b.scales[scale]>>4);int ar=token*E+expert;expect+=double(weight)*qs[ar*K+k]*ds[(ar*K+k)/32];}float got;ck(cudaMemcpy(&got,out+((size_t)token*E+expert)*N+row,4,cudaMemcpyDeviceToHost));double err=fabs(got-expect);maxerr=std::max(maxerr,err);if(err>5e-5+fabs(expect)*1e-5){fprintf(stderr,"Q2K dequant guard B%d err%g expect%g got%g\n",B,err,expect,got);return 5;}}
printf("{\"rows\":%d,\"dequant_float64_guard_values\":16,\"max_abs_vs_dequant_float64\":%.9g,\"dequant_guard_pass\":true}\n",B,maxerr);ck(cudaFree(ad));ck(cudaFree(sd));ck(cudaFree(qd));ck(cudaFree(out));ck(cudaFree(ref));}}
